// Canvas-based ad template renderer using @napi-rs/canvas
// Works on Vercel Lambda (prebuilt Skia binaries for linux-x64)

const { createCanvas, GlobalFonts } = require('@napi-rs/canvas');

// Fonts embedded as base64 — eliminates file path issues in Lambda
const _FA = '';
const _FR = '';
const _FB = '';
try {
  GlobalFonts.register(Buffer.from(_FR, 'base64'), 'Inter');
  GlobalFonts.register(Buffer.from(_FB, 'base64'), 'Inter');
  GlobalFonts.register(Buffer.from(_FA, 'base64'), 'Anton');
} catch (e) {
  console.warn('[adTemplates] Font registration failed:', e.message);
}

const DIMS = {
  square:     { w: 1080, h: 1080 },
  vertical:   { w: 1080, h: 1920 },
  horizontal: { w: 1920, h: 1080 },
};

// ─── DRAWING HELPERS ─────────────────────────────────────────────────────────

function hexToRgba(hex, alpha) {
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

function fadeRect(ctx, x, y, w, h, fromColor, toColor, vertical = true) {
  const grad = vertical
    ? ctx.createLinearGradient(x, y, x, y + h)
    : ctx.createLinearGradient(x, y, x + w, y);
  grad.addColorStop(0, fromColor);
  grad.addColorStop(1, toColor);
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
}

function roundRect(ctx, x, y, w, h, r, fill, stroke, strokeWidth = 2) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.arcTo(x + w, y, x + w, y + r, r);
  ctx.lineTo(x + w, y + h - r);
  ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
  ctx.lineTo(x + r, y + h);
  ctx.arcTo(x, y + h, x, y + h - r, r);
  ctx.lineTo(x, y + r);
  ctx.arcTo(x, y, x + r, y, r);
  ctx.closePath();
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = strokeWidth; ctx.stroke(); }
}

function shadowOn(ctx, blur = 8, dy = 3) {
  ctx.shadowColor = 'rgba(0,0,0,0.95)';
  ctx.shadowBlur = blur;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = dy;
}
function shadowOff(ctx) {
  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
}

function txt(ctx, text, x, y, size, weight, color, align = 'left', maxWidth, shadow = true, fontFamily = 'Inter') {
  ctx.font = `${weight} ${size}px ${fontFamily}, sans-serif`;
  ctx.fillStyle = color;
  ctx.textAlign = align;
  if (shadow) shadowOn(ctx, Math.round(size * 0.18), Math.round(size * 0.08));
  if (maxWidth) ctx.fillText(text, x, y, maxWidth);
  else ctx.fillText(text, x, y);
  if (shadow) shadowOff(ctx);
}

function wrapText(ctx, text, x, y, maxWidth, size, weight, color, lineHeight, align = 'left', shadow = true, fontFamily = 'Inter') {
  ctx.font = `${weight} ${size}px ${fontFamily}, sans-serif`;
  ctx.fillStyle = color;
  ctx.textAlign = align;
  if (shadow) shadowOn(ctx, Math.round(size * 0.18), Math.round(size * 0.08));
  const words = String(text).split(' ');
  let line = '';
  let curY = y;
  for (const word of words) {
    const test = line ? `${line} ${word}` : word;
    if (ctx.measureText(test).width > maxWidth && line) {
      ctx.fillText(line, x, curY);
      line = word;
      curY += lineHeight;
    } else {
      line = test;
    }
  }
  if (line) ctx.fillText(line, x, curY);
  if (shadow) shadowOff(ctx);
  return curY + lineHeight;
}

function pill(ctx, x, y, w, h, fill, text, textColor, size) {
  roundRect(ctx, x, y, w, h, h / 2, fill);
  txt(ctx, text, x + w / 2, y + h / 2 + size * 0.36, size, 'bold', textColor, 'center');
}

// Full-width CTA button + secondary sub-line (matches clickads/cienads style)
function ctaFull(ctx, canvasW, canvasH, fill, text, sub) {
  pill(ctx, 32, canvasH - 132, canvasW - 64, 84, fill, text, '#fff', 36);
  txt(ctx, sub || 'Toca para ver más →', canvasW / 2, canvasH - 26, 18, 'normal', 'rgba(255,255,255,0.65)', 'center', canvasW - 80, false);
}

function drawCheck(ctx, cx, cy, r, color) {
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = r * 0.35;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.beginPath();
  ctx.moveTo(cx - r * 0.45, cy);
  ctx.lineTo(cx - r * 0.1, cy + r * 0.4);
  ctx.lineTo(cx + r * 0.45, cy - r * 0.35);
  ctx.stroke();
  ctx.restore();
}

function drawStars(ctx, x, y, count, size, color) {
  for (let i = 0; i < count; i++) {
    const cx = x + i * (size + 4);
    ctx.save();
    ctx.fillStyle = color;
    ctx.beginPath();
    for (let p = 0; p < 5; p++) {
      const a = (p * 4 * Math.PI) / 5 - Math.PI / 2;
      const ai = a + (2 * Math.PI) / 5;
      if (p === 0) ctx.moveTo(cx + size * Math.cos(a), y + size * Math.sin(a));
      else ctx.lineTo(cx + size * Math.cos(a), y + size * Math.sin(a));
      ctx.lineTo(cx + (size * 0.4) * Math.cos(ai), y + (size * 0.4) * Math.sin(ai));
    }
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
}

function bullets(ctx, items, x, y, color, textColor, size, spacing, maxWidth) {
  const cr = Math.max(14, Math.round(size * 0.52));
  items.forEach((item, i) => {
    const cy = y + i * spacing;
    drawCheck(ctx, x + cr + 2, cy - Math.round(size * 0.14), cr, color);
    txt(ctx, item, x + cr * 2 + 12, cy, size, 'normal', textColor, 'left', maxWidth);
  });
}

function crossItems(ctx, items, x, y, size, spacing) {
  items.forEach((item, i) => {
    const cy = y + i * spacing;
    roundRect(ctx, x, cy - size, size, size, 3, '#ef4444');
    txt(ctx, 'X', x + size / 2, cy - 4, size - 6, 'bold', '#fff', 'center');
    txt(ctx, item, x + size + 10, cy, size, 'normal', '#cbd5e1', 'left');
  });
}

function avatarCard(ctx, x, y, w, h, color, initial, testimonial, reviewer) {
  roundRect(ctx, x, y, w, h, 14, 'rgba(255,255,255,0.12)', color, 2);
  ctx.beginPath();
  ctx.arc(x + 38, y + h / 2, 26, 0, Math.PI * 2);
  ctx.fillStyle = color;
  ctx.globalAlpha = 0.85;
  ctx.fill();
  ctx.globalAlpha = 1;
  txt(ctx, initial, x + 38, y + h / 2 + 8, 22, 'bold', '#fff', 'center');
  const t = testimonial.length > 46 ? testimonial.slice(0, 46) + '...' : testimonial;
  txt(ctx, t, x + 76, y + h / 2 - 12, 20, 'bold', '#fff', 'left');
  drawStars(ctx, x + 76, y + h / 2 + 16, 5, 8, color);
  txt(ctx, `— ${reviewer}`, x + 76 + 5 * 13, y + h / 2 + 16, 18, 'normal', color, 'left');
}

// ─── TEMPLATES ───────────────────────────────────────────────────────────────

function templatePain(copy, color, w, h, hasProduct) {
  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  fadeRect(ctx, 0, 0, w, h * 0.52, 'rgba(0,0,0,0.54)', 'rgba(0,0,0,0)');
  fadeRect(ctx, 0, h * 0.54, w, h * 0.46, 'rgba(0,0,0,0)', 'rgba(0,0,0,0.70)');

  ctx.fillStyle = color; ctx.fillRect(0, 0, w, 10);

  // PROBLEMA badge
  roundRect(ctx, 28, 20, 186, 46, 23, '#e11d48');
  txt(ctx, '⚠ PROBLEMA', 121, 51, 24, 'bold', '#fff', 'center', undefined, false);

  // Big headline
  const headY = wrapText(ctx, copy.headline || '¿Cansado de no ver resultados?',
    w / 2, 96, w - 60, 72, 'bold', '#ffffff', 90, 'center');

  // Empathy line with backdrop
  const subtext = (copy.primaryText || 'Sabemos lo frustrante que es.').split('.')[0] + '.';
  roundRect(ctx, 30, headY + 2, w - 60, 56, 8, 'rgba(0,0,0,0.50)');
  txt(ctx, subtext, w / 2, headY + 38, 30, 'normal', '#f1f5f9', 'center', w - 80);

  const bY = Math.round(h * 0.60);
  const bItems = [
    copy.b1 || 'Solución probada y efectiva',
    copy.b2 || 'Resultados desde la primera semana',
    copy.b3 || 'Sin efectos secundarios',
  ];
  const bulletMaxW = hasProduct ? Math.round(w * 0.50) : w - 76;
  bullets(ctx, bItems, 34, bY, color, '#fff', 34, 68, bulletMaxW);

  ctaFull(ctx, w, h, color, copy.cta || 'Ver Solución');
  ctx.fillStyle = color; ctx.fillRect(0, h - 10, w, 10);

  return canvas.toBuffer('image/png');
}

function templateDesire(copy, color, w, h, hasProduct, variation = 0) {
  if (variation === 1) return templateDesireV1(copy, color, w, h, hasProduct);

  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  // Subtle top vignette only — let the AI background breathe
  fadeRect(ctx, 0, 0, w, Math.round(h * 0.42), 'rgba(0,0,0,0.54)', 'rgba(0,0,0,0.0)');

  // ── Massive 2-color headline in top 40% ──────────────────────────────────
  const FS = 114;
  const LH = 126;
  const headline = (copy.headline || 'LOGRA EL RESULTADO QUE SIEMPRE QUISISTE').toUpperCase();
  const hWords = headline.split(' ');
  const mid = Math.ceil(hWords.length / 2);
  const line1 = hWords.slice(0, mid).join(' ');
  const line2 = hWords.slice(mid).join(' ');

  txt(ctx, line1, w / 2, 76 + FS, FS, 'normal', '#ffffff', 'center', w - 60, true, 'Anton');
  if (line2) txt(ctx, line2, w / 2, 76 + FS + LH, FS, 'normal', color, 'center', w - 60, true, 'Anton');

  // ── Brand accent circle top-right ─────────────────────────────────────────
  ctx.save();
  ctx.beginPath();
  ctx.arc(w - 60, 60, 42, 0, Math.PI * 2);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.restore();
  drawStars(ctx, w - 76, 60, 3, 12, '#fff');

  // ── Bottom benefit pill ───────────────────────────────────────────────────
  const pillH = 188;
  const pillY = h - pillH - 24;
  roundRect(ctx, 28, pillY, w - 56, pillH, 22, color);

  const cx = w / 2;
  const pmW = w - 120;
  txt(ctx, copy.b1 || 'Resultados reales y visibles', cx, pillY + 56, 32, 'bold', '#fff', 'center', pmW, false);
  txt(ctx, copy.b2 || 'Fórmula premium comprobada', cx, pillY + 104, 27, 'normal', 'rgba(255,255,255,0.90)', 'center', pmW, false);
  txt(ctx, copy.b3 || 'Amplia satisfacción garantizada', cx, pillY + 146, 23, 'normal', 'rgba(255,255,255,0.76)', 'center', pmW, false);

  return canvas.toBuffer('image/png');
}

function templateDesireV1(copy, color, w, h, hasProduct) {
  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  // Photo visible — just subtle fades top and bottom
  fadeRect(ctx, 0, 0, w, Math.round(h * 0.44), 'rgba(0,0,0,0.50)', 'rgba(0,0,0,0.0)');
  fadeRect(ctx, 0, Math.round(h * 0.68), w, Math.round(h * 0.32), 'rgba(0,0,0,0.0)', 'rgba(0,0,0,0.58)');

  // ── Massive 2-color headline (same as V0 but smaller split) ──────────────
  const FS = 114;
  const LH = 126;
  const headline = (copy.headline || 'LOGRA EL RESULTADO QUE SIEMPRE QUISISTE').toUpperCase();
  const hWords = headline.split(' ');
  // V1 splits at 1/3 so line 2 (brand color) is longer and more prominent
  const mid = Math.max(1, Math.floor(hWords.length / 3));
  const line1 = hWords.slice(0, mid).join(' ');
  const line2 = hWords.slice(mid).join(' ');

  txt(ctx, line1, w / 2, 76 + FS, FS, 'normal', '#ffffff', 'center', w - 60, true, 'Anton');
  if (line2) txt(ctx, line2, w / 2, 76 + FS + LH, FS, 'normal', color, 'center', w - 60, true, 'Anton');

  // ── Social proof badge — bottom left ──────────────────────────────────────
  const spY = h - 212;
  drawStars(ctx, 36, spY, 5, 11, '#f59e0b');
  txt(ctx, '+10,000 clientes satisfechos', 36 + 5 * 26, spY + 8, 20, 'bold', '#f59e0b', 'left', 400, false);

  // ── Two benefit chips side by side ────────────────────────────────────────
  const chipH = 74;
  const gap = 12;
  const chipW = Math.round((w - 72 - gap) / 2);
  const chipY = h - chipH - 96;

  roundRect(ctx, 36, chipY, chipW, chipH, chipH / 2, color);
  txt(ctx, copy.b1 || 'Resultados reales', 36 + chipW / 2, chipY + chipH / 2 + 11, 22, 'bold', '#fff', 'center', chipW - 24, false);

  const chip2X = 36 + chipW + gap;
  roundRect(ctx, chip2X, chipY, chipW, chipH, chipH / 2, color);
  txt(ctx, copy.b2 || 'Fórmula premium', chip2X + chipW / 2, chipY + chipH / 2 + 11, 22, 'bold', '#fff', 'center', chipW - 24, false);

  // ── Third benefit + sub-CTA at very bottom ────────────────────────────────
  txt(ctx, copy.b3 || 'Amplia satisfacción garantizada', w / 2, h - 48, 22, 'normal', 'rgba(255,255,255,0.80)', 'center', w - 80, false);
  txt(ctx, copy.cta ? `${copy.cta} →` : 'Toca para ver más →', w / 2, h - 18, 18, 'bold', 'rgba(255,255,255,0.55)', 'center', w - 80, false);

  return canvas.toBuffer('image/png');
}

function templateTransformation(copy, color, w, h) {
  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  const half = Math.round(w / 2);

  // Moderate overlays — let the AI split background breathe
  fadeRect(ctx, 0, 0, half, h, 'rgba(0,0,0,0.68)', 'rgba(0,0,0,0.08)', false);
  fadeRect(ctx, half, 0, half, h, hexToRgba(color, 0.10), hexToRgba(color, 0.46), false);
  fadeRect(ctx, 0, h * 0.62, w, h * 0.38, 'rgba(0,0,0,0)', 'rgba(0,0,0,0.88)');

  // Divider line
  ctx.fillStyle = color; ctx.fillRect(half - 3, 0, 6, h);

  // VS badge (bigger)
  ctx.beginPath(); ctx.arc(half, Math.round(h * 0.22), 48, 0, Math.PI * 2);
  ctx.fillStyle = color; ctx.fill();
  txt(ctx, 'VS', half, Math.round(h * 0.22) + 16, 34, 'bold', '#fff', 'center');

  // ANTES / DESPUÉS labels
  roundRect(ctx, 18, 18, 152, 54, 8, '#1e293b');
  txt(ctx, 'ANTES', 94, 54, 30, 'bold', '#9ca3af', 'center', undefined, false);
  roundRect(ctx, half + 18, 18, 190, 54, 8, color);
  txt(ctx, 'DESPUÉS', half + 113, 54, 30, 'bold', '#fff', 'center', undefined, false);

  // Panel texts from copy fields
  const beforeText = copy.b1 || 'Sin resultados. Frustración constante.';
  const afterText = copy.a1 || 'Resultados reales. Confianza renovada.';
  wrapText(ctx, beforeText, Math.round(half * 0.5), Math.round(h * 0.38), half - 56, 34, 'bold', '#9ca3af', 46, 'center');
  wrapText(ctx, afterText, Math.round(half + half * 0.5), Math.round(h * 0.38), half - 56, 34, 'bold', '#fff', 46, 'center');

  // Product/headline tagline
  const tagline = (copy.headline || 'EL CAMBIO QUE NECESITAS').toUpperCase().slice(0, 40);
  wrapText(ctx, tagline, w / 2, Math.round(h * 0.72), w - 80, 36, 'bold', color, 46, 'center');

  ctaFull(ctx, w, h, color, copy.cta || 'EMPIEZA EL CAMBIO');
  ctx.fillStyle = color; ctx.fillRect(0, 0, w, 8); ctx.fillRect(0, h - 8, w, 8);

  return canvas.toBuffer('image/png');
}

function templateObjection(copy, color, w, h) {
  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  const half = Math.round(w / 2);
  const M = 14;
  const R = 22;
  const BW = 6;
  const HEAD = 128;
  const DANGER = '#e11d48';
  const panelW = half - M * 2;
  const panelH = h - 88 - M; // space for bottom banner

  // helper: header shape with rounded top, flat bottom
  const topRound = (x, y, bw, bh, br, fill) => {
    ctx.beginPath();
    ctx.moveTo(x + br, y);
    ctx.lineTo(x + bw - br, y);
    ctx.arc(x + bw - br, y + br, br, -Math.PI / 2, 0);
    ctx.lineTo(x + bw, y + bh);
    ctx.lineTo(x, y + bh);
    ctx.arc(x + br, y + br, br, Math.PI, Math.PI * 1.5);
    ctx.closePath();
    ctx.fillStyle = fill; ctx.fill();
  };

  // ── LEFT PANEL (problem) ─────────────────────────────────────────────────
  roundRect(ctx, M, M, panelW, panelH, R, 'rgba(255,255,255,0.95)');
  topRound(M, M, panelW, HEAD, R, DANGER);
  roundRect(ctx, M, M, panelW, panelH, R, null, DANGER, BW);

  txt(ctx, '✕', M + 50, M + HEAD / 2 + 18, 58, 'bold', '#fff', 'center', undefined, false);
  wrapText(ctx, copy.headline?.slice(0, 44) || '¿Por qué esto no ha funcionado?',
    M + 100, M + 22, panelW - 110, 42, 'bold', '#fff', 54, 'left', false);

  const probs = [
    copy.p1 || 'Sin resultados visibles',
    copy.p2 || 'Problema que persiste sin solución',
    copy.p3 || 'Frustración y dinero perdido',
  ];
  probs.forEach((p, i) => {
    const py = M + HEAD + 30 + i * 105;
    txt(ctx, '•', M + 26, py + 30, 58, 'bold', DANGER, 'left', undefined, false);
    wrapText(ctx, p, M + 64, py, panelW - 74, 36, 'bold', '#1e293b', 48, 'left', false);
  });

  // ── RIGHT PANEL (solution) ────────────────────────────────────────────────
  const rx = half + M;
  roundRect(ctx, rx, M, panelW, panelH, R, 'rgba(255,255,255,0.97)');
  topRound(rx, M, panelW, HEAD, R, color);
  roundRect(ctx, rx, M, panelW, panelH, R, null, color, BW);

  txt(ctx, '✓', rx + 50, M + HEAD / 2 + 18, 58, 'bold', '#fff', 'center', undefined, false);
  wrapText(ctx, 'La solución real',
    rx + 100, M + 22, panelW - 110, 42, 'bold', '#fff', 54, 'left', false);

  const sols = [
    copy.s1 || 'Resultados visibles y duraderos',
    copy.s2 || 'Fórmula premium comprobada',
    copy.s3 || 'Sin efectos secundarios',
  ];
  sols.forEach((s, i) => {
    const sy = M + HEAD + 30 + i * 105;
    txt(ctx, '•', rx + 26, sy + 30, 58, 'bold', color, 'left', undefined, false);
    wrapText(ctx, s, rx + 64, sy, panelW - 74, 36, 'bold', '#1e293b', 48, 'left', false);
  });

  // ── BOTTOM BANNER ─────────────────────────────────────────────────────────
  const bannerY = h - 80;
  roundRect(ctx, M, bannerY, w - M * 2, 66, 16, color);
  const bannerTxt = copy.description ? copy.description.toUpperCase() : 'PRODUCTO GARANTIZADO · RESULTADOS COMPROBADOS';
  txt(ctx, bannerTxt, w / 2, bannerY + 40, 28, 'bold', '#fff', 'center', w - 60, false);

  return canvas.toBuffer('image/png');
}

function templateUrgency(copy, color, w, h) {
  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  fadeRect(ctx, 0, 0, w, h * 0.48, 'rgba(0,0,0,0.52)', 'rgba(0,0,0,0)');
  fadeRect(ctx, 0, h * 0.48, w, h * 0.52, 'rgba(0,0,0,0)', 'rgba(0,0,0,0.68)');

  ctx.fillStyle = color; ctx.fillRect(0, 0, w, 10);

  // Urgency badge top-right (bigger)
  ctx.beginPath(); ctx.arc(w - 102, 114, 82, 0, Math.PI * 2);
  ctx.fillStyle = color; ctx.globalAlpha = 0.95; ctx.fill(); ctx.globalAlpha = 1;
  txt(ctx, 'SOLO', w - 102, 92, 28, 'bold', '#fff', 'center', undefined, false);
  txt(ctx, 'HOY', w - 102, 126, 28, 'bold', '#fff', 'center', undefined, false);

  // Big headline
  wrapText(ctx, copy.headline || '¡Oferta por tiempo limitado!',
    w / 2 - 44, 94, w - 230, 70, 'bold', '#fff', 86, 'center');

  // Sub-copy with backdrop
  const sub = copy.description || copy.primaryText?.split('.')[0] || 'Resultados garantizados desde la primera semana';
  roundRect(ctx, 24, Math.round(h * 0.47) - 36, w - 48, 60, 10, 'rgba(0,0,0,0.45)');
  txt(ctx, sub, w / 2, Math.round(h * 0.47) + 6, 30, 'normal', 'rgba(255,255,255,0.92)', 'center', w - 80);

  // Feature circles (bigger radius, bigger labels)
  const featureLabels = [
    copy.f1 || 'Resultados\nreales',
    copy.f2 || 'Envío\ngratis',
    copy.f3 || 'Garantía\ntotal',
    copy.f4 || 'Sin\nriesgos',
  ];
  const circR = 56;
  const circleBaseY = Math.round(h * 0.65);
  const step = Math.round(w / 4);
  featureLabels.forEach((label, i) => {
    const cx = Math.round(step * i + step / 2);
    ctx.beginPath(); ctx.arc(cx, circleBaseY, circR, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255,255,255,0.55)'; ctx.lineWidth = 3; ctx.stroke();
    ctx.beginPath(); ctx.arc(cx, circleBaseY, circR - 7, 0, Math.PI * 2);
    ctx.fillStyle = color; ctx.globalAlpha = 0.88; ctx.fill(); ctx.globalAlpha = 1;
    label.split('\n').forEach((line, li) => {
      txt(ctx, line.toUpperCase(), cx, circleBaseY + circR + 28 + li * 30, 24, 'bold', '#fff', 'center', step - 14, false);
    });
  });

  ctx.fillStyle = color; ctx.fillRect(0, circleBaseY - circR - 16, w, 4);

  ctaFull(ctx, w, h, color, copy.cta || '¡Compra ahora!', 'Oferta válida hoy →');
  ctx.fillStyle = color; ctx.fillRect(0, h - 10, w, 10);

  return canvas.toBuffer('image/png');
}

function templateAuthority(copy, color, w, h, hasProduct) {
  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  // Light overlays — professional bright background shows through
  fadeRect(ctx, 0, 0, w, h * 0.28, 'rgba(0,0,0,0.28)', 'rgba(0,0,0,0)');
  fadeRect(ctx, 0, h * 0.78, w, h * 0.22, 'rgba(0,0,0,0)', 'rgba(0,0,0,0.52)');

  ctx.fillStyle = color; ctx.fillRect(0, 0, w, 10);

  // Headline on white panel
  roundRect(ctx, 20, 16, w - 40, 118, 16, 'rgba(255,255,255,0.95)');
  wrapText(ctx, copy.headline || 'Fórmula premium respaldada por expertos',
    w / 2, 52, w - 80, 46, 'bold', '#111827', 62, 'center', undefined, false);

  // Accreditation badge below headline
  roundRect(ctx, w / 2 - 170, 150, 340, 52, 26, color);
  txt(ctx, '★ AVALADO POR EXPERTOS', w / 2, 182, 24, 'bold', '#fff', 'center', undefined, false);

  // Feature panel — always on LEFT, width restricted when product on right
  const panelX = 20;
  const panelW = hasProduct ? Math.round(w * 0.46) : w - 40;
  const panelY = 218;
  const panelH = Math.round(h * 0.40);
  roundRect(ctx, panelX, panelY, panelW, panelH, 18, 'rgba(255,255,255,0.96)');

  const feats = [
    copy.f1 || 'Ingredientes certificados de calidad',
    copy.f2 || 'Resultados comprobados clínicamente',
    copy.f3 || 'Sin efectos secundarios',
    copy.f4 || 'Estándares de fabricación premium',
  ];
  const featSpacing = Math.round(panelH / 4.2);
  feats.forEach((f, i) => {
    const fy = panelY + 20 + i * featSpacing;
    ctx.beginPath(); ctx.arc(panelX + 22, fy + 14, 11, 0, Math.PI * 2);
    ctx.fillStyle = color; ctx.fill();
    txt(ctx, f, panelX + 42, fy + 18, 26, 'bold', '#111827', 'left', panelW - 56, false);
  });

  ctaFull(ctx, w, h, color, copy.cta || 'Ver más');
  ctx.fillStyle = color; ctx.fillRect(0, h - 10, w, 10);

  return canvas.toBuffer('image/png');
}

function templateComparison(copy, color, w, h) {
  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  // White wash — AI split background shows faintly
  ctx.fillStyle = 'rgba(255,255,255,0.82)'; ctx.fillRect(0, 0, w, h);

  const col = Math.round(w / 3);
  const M = 14;
  const R = 22;
  const BW = 6;
  const HEAD = 76;
  const cardY = 148;
  const cardH = Math.round(h * 0.64);
  const DARK = '#1e293b';

  // helper: top-rounded header shape
  const topRound = (x, y, bw, bh, br, fill) => {
    ctx.beginPath();
    ctx.moveTo(x + br, y);
    ctx.lineTo(x + bw - br, y);
    ctx.arc(x + bw - br, y + br, br, -Math.PI / 2, 0);
    ctx.lineTo(x + bw, y + bh);
    ctx.lineTo(x, y + bh);
    ctx.arc(x + br, y + br, br, Math.PI, Math.PI * 1.5);
    ctx.closePath();
    ctx.fillStyle = fill; ctx.fill();
  };

  // ── TOP HEADLINE (above cards) ────────────────────────────────────────────
  const headline = copy.headline || 'COMPARA Y DECIDE\nTÚ MISMO';
  wrapText(ctx, headline, w / 2, 24, w - 60, 48, 'bold', DARK, 62, 'center', false);

  // ── LEFT CARD (ANTES) ─────────────────────────────────────────────────────
  const lx = M;
  const cw = col - M * 2;
  roundRect(ctx, lx, cardY, cw, cardH, R, 'rgba(255,255,255,0.96)');
  topRound(lx, cardY, cw, HEAD, R, DARK);
  roundRect(ctx, lx, cardY, cw, cardH, R, null, DARK, BW);
  txt(ctx, 'ANTES', lx + cw / 2, cardY + 48, 34, 'bold', '#fff', 'center', undefined, false);

  const befores = [copy.b1 || 'Sin resultados visibles', copy.b2 || 'Problema sin resolver'];
  befores.forEach((d, i) => {
    const dy = cardY + HEAD + 28 + i * 116;
    roundRect(ctx, lx + 14, dy, cw - 28, 100, 14, 'rgba(15,23,42,0.07)');
    wrapText(ctx, d, lx + cw / 2, dy + 18, cw - 48, 32, 'bold', '#374151', 42, 'center', false);
  });

  // ── CENTER COLUMN ─────────────────────────────────────────────────────────
  const cx = col;
  const ccw = col;
  const centerLabel = copy.productName
    ? `${copy.productName.toUpperCase().slice(0, 26)}\nLA SOLUCIÓN\nCOMPROBADA`
    : 'LA SOLUCIÓN\nCOMPROBADA';
  // Product is composited by compositeAll — just add bottom text
  // Product label at TOP of center column (above product which is composited at h*0.32)
  wrapText(ctx, centerLabel, cx + ccw / 2, cardY + 20, ccw - 20, 26, 'bold', DARK, 36, 'center', false);

  // ── RIGHT CARD (DESPUÉS) ──────────────────────────────────────────────────
  const rx2 = col * 2 + M;
  roundRect(ctx, rx2, cardY, cw, cardH, R, hexToRgba(color, 0.08));
  topRound(rx2, cardY, cw, HEAD, R, color);
  roundRect(ctx, rx2, cardY, cw, cardH, R, null, color, BW);
  txt(ctx, 'DESPUÉS', rx2 + cw / 2, cardY + 48, 34, 'bold', '#fff', 'center', undefined, false);

  const afters = [copy.a1 || 'Resultados reales y visibles', copy.a2 || 'Problema resuelto'];
  afters.forEach((d, i) => {
    const dy = cardY + HEAD + 28 + i * 116;
    roundRect(ctx, rx2 + 14, dy, cw - 28, 100, 14, hexToRgba(color, 0.12));
    wrapText(ctx, d, rx2 + cw / 2, dy + 18, cw - 48, 32, 'bold', color, 42, 'center', false);
  });

  // ── BOTTOM TAGLINE ────────────────────────────────────────────────────────
  const tagline = copy.primaryText ? copy.primaryText.split('.')[0] + '.' : 'Resultados visibles en semanas. Satisfacción garantizada.';
  txt(ctx, tagline, w / 2, cardY + cardH + 40, 24, 'normal', '#6b7280', 'center', w - 60, false);

  return canvas.toBuffer('image/png');
}

function templateGuarantee(copy, color, w, h, hasProduct) {
  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  fadeRect(ctx, 0, 0, w, h * 0.48, 'rgba(0,0,0,0.54)', 'rgba(0,0,0,0)');
  fadeRect(ctx, 0, h * 0.55, w, h * 0.45, 'rgba(0,0,0,0)', 'rgba(0,0,0,0.72)');
  ctx.fillStyle = color; ctx.fillRect(0, 0, w, 10);

  // Shield badge (bigger ✓ icon)
  roundRect(ctx, w / 2 - 90, 18, 180, 148, 26, color);
  roundRect(ctx, w / 2 - 66, 34, 132, 112, 18, 'rgba(255,255,255,0.18)');
  txt(ctx, '✓', w / 2, 116, 60, 'bold', '#fff', 'center', undefined, false);
  txt(ctx, 'GRTIA', w / 2, 154, 26, 'bold', '#fff', 'center', undefined, false);

  txt(ctx, 'Garantía total', w / 2, 206, 60, 'bold', '#fff', 'center');
  txt(ctx, 'de devolución', w / 2, 264, 42, 'bold', color, 'center');
  pill(ctx, w / 2 - 210, 282, 420, 64, color, '100% GARANTIZADO', '#fff', 30);

  const terms = (copy.primaryText || 'Si no ves resultados en 30 días, te devolvemos tu dinero sin preguntas.').split('.')[0] + '.';
  roundRect(ctx, 30, 364, w - 60, 60, 8, 'rgba(0,0,0,0.42)');
  txt(ctx, terms, w / 2, 400, 26, 'normal', '#e2e8f0', 'center', w - 80);

  const bItems = [
    copy.b1 || 'Devolución completa si no funciona',
    copy.b2 || 'Sin preguntas ni trámites',
    copy.b3 || 'Proceso simple y rápido',
  ];
  const bulletMaxW = hasProduct ? Math.round(w * 0.48) : w - 76;
  bullets(ctx, bItems, 34, Math.round(h * 0.62), color, '#fff', 34, 68, bulletMaxW);

  ctaFull(ctx, w, h, color, copy.cta || '¡Compra sin riesgo!', 'Sin riesgo · Devolución garantizada →');
  ctx.fillStyle = color; ctx.fillRect(0, h - 10, w, 10);

  return canvas.toBuffer('image/png');
}

function templateSocialProof(copy, color, w, h) {
  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  // Light overlay — photo breathes like clickads
  fadeRect(ctx, 0, 0, w, h * 0.42, 'rgba(0,0,0,0.50)', 'rgba(0,0,0,0)');
  fadeRect(ctx, 0, h * 0.54, w, h * 0.46, 'rgba(0,0,0,0)', 'rgba(0,0,0,0.68)');
  ctx.fillStyle = color; ctx.fillRect(0, 0, w, 10);

  // Social proof headline
  txt(ctx, '+10,000', w / 2, 108, 96, 'bold', '#fff', 'center');
  txt(ctx, 'clientes satisfechos', w / 2, 160, 40, 'bold', '#fff', 'center');
  drawStars(ctx, w / 2 - 5 * 20, 204, 5, 15, '#f59e0b');
  txt(ctx, '4.9/5 · Más de 800 reseñas verificadas', w / 2, 242, 24, 'normal', 'rgba(255,255,255,0.80)', 'center');

  // Floating testimonial cards — HIGH opacity white (clickads style)
  const r1 = copy.r1 || '¡Increíble, lo noté desde la primera semana de uso!';
  const r2 = copy.r2 || 'Superó todas mis expectativas. 100% recomendado.';
  const cardW = w - 56;
  const cardH = 134;
  const cardY1 = Math.round(h * 0.54);

  // Card 1 — drop shadow simulation + opaque white
  roundRect(ctx, 32, cardY1 + 5, cardW, cardH, 18, 'rgba(0,0,0,0.18)');
  roundRect(ctx, 28, cardY1, cardW, cardH, 18, 'rgba(255,255,255,0.97)');
  ctx.beginPath(); ctx.arc(72, cardY1 + cardH / 2, 36, 0, Math.PI * 2);
  ctx.fillStyle = color; ctx.fill();
  txt(ctx, 'C', 72, cardY1 + cardH / 2 + 12, 32, 'bold', '#fff', 'center', undefined, false);
  drawStars(ctx, 120, cardY1 + 32, 5, 10, '#f59e0b');
  const t1 = r1.length > 58 ? r1.slice(0, 58) + '…' : r1;
  wrapText(ctx, t1, 120, cardY1 + 60, cardW - 108, 26, 'bold', '#111827', 36, 'left', false);
  txt(ctx, '— Camila R.  ✓ Compra verificada', 120, cardY1 + cardH - 18, 18, 'normal', color, 'left', cardW - 108, false);

  // Card 2
  const cardY2 = cardY1 + cardH + 16;
  roundRect(ctx, 32, cardY2 + 5, cardW, cardH, 18, 'rgba(0,0,0,0.18)');
  roundRect(ctx, 28, cardY2, cardW, cardH, 18, 'rgba(255,255,255,0.97)');
  ctx.beginPath(); ctx.arc(72, cardY2 + cardH / 2, 36, 0, Math.PI * 2);
  ctx.fillStyle = color; ctx.fill();
  txt(ctx, 'D', 72, cardY2 + cardH / 2 + 12, 32, 'bold', '#fff', 'center', undefined, false);
  drawStars(ctx, 120, cardY2 + 32, 5, 10, '#f59e0b');
  const t2 = r2.length > 58 ? r2.slice(0, 58) + '…' : r2;
  wrapText(ctx, t2, 120, cardY2 + 60, cardW - 108, 26, 'bold', '#111827', 36, 'left', false);
  txt(ctx, '— Diego M.  ✓ Compra verificada', 120, cardY2 + cardH - 18, 18, 'normal', color, 'left', cardW - 108, false);

  ctaFull(ctx, w, h, color, copy.cta || '¡Únete a ellos!', 'Únete a miles de clientes satisfechos →');
  ctx.fillStyle = color; ctx.fillRect(0, h - 10, w, 10);

  return canvas.toBuffer('image/png');
}

function templateCuriosity(copy, color, w, h, hasProduct) {
  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  fadeRect(ctx, 0, 0, w, h * 0.55, 'rgba(0,0,0,0.56)', 'rgba(0,0,0,0)');
  fadeRect(ctx, 0, h * 0.55, w, h * 0.45, 'rgba(0,0,0,0)', 'rgba(0,0,0,0.72)');

  // Headline
  const headY = wrapText(ctx, copy.headline || '¿Sabías que la mayoría lo hace MAL?',
    w / 2, 84, w - 60, 70, 'bold', '#fff', 88, 'center');

  // Color accent bar
  roundRect(ctx, w / 2 - 130, headY, 260, 6, 3, color);

  const subDesc = copy.description || 'Lo que nadie te había contado hasta ahora';
  roundRect(ctx, 30, headY + 12, w - 60, 56, 8, 'rgba(0,0,0,0.42)');
  txt(ctx, subDesc, w / 2, headY + 50, 30, 'normal', 'rgba(255,255,255,0.92)', 'center', w - 80);

  // Curiosity hints with bigger text and arrow badges
  const hintMaxW = hasProduct ? Math.round(w * 0.46) : w - 100;
  const hints = [
    copy.h1 || 'El error que todos cometen sin saberlo',
    copy.h2 || 'La solución que lo cambia todo',
    copy.h3 || 'Resultados que no esperabas posibles',
  ];
  hints.forEach((hint, i) => {
    const hy2 = Math.round(h * 0.62) + i * 70;
    roundRect(ctx, 34, hy2 - 28, 46, 46, 10, color);
    txt(ctx, '»', 57, hy2, 24, 'bold', '#fff', 'center', undefined, false);
    txt(ctx, hint, 94, hy2, 32, 'normal', '#f1f5f9', 'left', hintMaxW);
  });

  ctaFull(ctx, w, h, color, copy.cta || 'Descubre el secreto');
  ctx.fillStyle = color; ctx.fillRect(0, h - 10, w, 10);

  return canvas.toBuffer('image/png');
}

function templatePrice(copy, color, w, h) {
  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  fadeRect(ctx, 0, 0, w, h * 0.50, 'rgba(0,0,0,0.55)', 'rgba(0,0,0,0)');
  fadeRect(ctx, 0, h * 0.53, w, h * 0.47, 'rgba(0,0,0,0)', 'rgba(0,0,0,0.72)');

  // Color top header
  ctx.fillStyle = color; ctx.fillRect(0, 0, w, 76);
  txt(ctx, 'OFERTA ESPECIAL · TIEMPO LIMITADO', w / 2, 52, 34, 'bold', '#fff', 'center', undefined, false);

  // Strikethrough price
  txt(ctx, 'Precio normal: $150.000', w / 2, 164, 38, 'normal', '#94a3b8', 'center');
  ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 5; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(w * 0.12, 148); ctx.lineTo(w * 0.88, 148); ctx.stroke();

  // Big price impact
  txt(ctx, '50% OFF!', w / 2, 258, 100, 'bold', '#fff', 'center');
  txt(ctx, 'SOLO $75.000', w / 2, 318, 44, 'bold', color, 'center');

  // Dynamic description
  const desc = copy.description || 'Envío gratis + garantía 30 días incluida';
  roundRect(ctx, 30, Math.round(h * 0.62) - 34, w - 60, 60, 10, 'rgba(0,0,0,0.45)');
  txt(ctx, desc, w / 2, Math.round(h * 0.62) + 4, 30, 'normal', '#e2e8f0', 'center', w - 80);

  const scarcity = copy.b1 || 'Solo por esta semana · Quedan pocas unidades';
  txt(ctx, scarcity, w / 2, Math.round(h * 0.62) + 66, 28, 'bold', '#f87171', 'center', w - 60);

  ctaFull(ctx, w, h, color, copy.cta || '¡Aprovecha ahora!', 'Solo quedan pocas unidades →');
  ctx.fillStyle = color; ctx.fillRect(0, h - 10, w, 10);

  return canvas.toBuffer('image/png');
}

// ─── DISPATCHER ──────────────────────────────────────────────────────────────

const TEMPLATE_FNS = {
  pain:           templatePain,
  desire:         templateDesire,
  transformation: templateTransformation,
  objection:      templateObjection,
  urgency:        templateUrgency,
  authority:      templateAuthority,
  comparison:     templateComparison,
  guarantee:      templateGuarantee,
  social_proof:   templateSocialProof,
  curiosity:      templateCuriosity,
  price:          templatePrice,
};

/**
 * Returns a PNG Buffer for the given angle template.
 * @param {string} angle
 * @param {object} copy  - { headline, primaryText, description, cta, productName, ... }
 * @param {string} color - primary hex color
 * @param {string} format - 'square' | 'vertical' | 'horizontal'
 * @returns {Buffer} PNG buffer
 */
function buildTemplate(angle, copy, color, format, hasProduct = false, variation = 0) {
  const { w, h } = DIMS[format] || DIMS.square;
  const fn = TEMPLATE_FNS[angle] || TEMPLATE_FNS.desire;
  return fn(copy || {}, color || '#6366f1', w, h, hasProduct, variation);
}

module.exports = { buildTemplate, DIMS };
